using namespace std;

class Solution {
public:
    int minimumIncompatibility(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> counts(17, 0);
        for (int x : nums) {
            if (++counts[x] > k) return -1;
        }
        int sz = n / k;
        if (sz == 1) return 0;
        vector<pair<int, int>> valid;
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) == sz) {
                int seen = 0;
                int mn = 100, mx = -1;
                bool ok = true;
                for (int i = 0; i < n; ++i) {
                    if (mask & (1 << i)) {
                        int v = nums[i];
                        if (seen & (1 << v)) { ok = false; break; }
                        seen |= (1 << v);
                        mn = min(mn, v);
                        mx = max(mx, v);
                    }
                }
                if (ok) valid.push_back({mask, mx - mn});
            }
        }
        vector<int> dp(1 << n, 1e9);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (dp[mask] == 1e9) continue;
            int first_unset = 0;
            while (first_unset < n && (mask & (1 << first_unset))) first_unset++;
            if (first_unset == n) continue;
            for (auto& [sub, cost] : valid) {
                if ((sub & (1 << first_unset)) && (mask & sub) == 0) {
                    dp[mask | sub] = min(dp[mask | sub], dp[mask] + cost);
                }
            }
        }
        return dp[(1 << n) - 1] >= 1e9 ? -1 : dp[(1 << n) - 1];
    }
};

import java.util.*;

class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        int[] counts = new int[17];
        for (int x : nums) {
            if (++counts[x] > k) return -1;
        }
        int sz = n / k;
        if (sz == 1) return 0;
        List<int[]> valid = new ArrayList<>();
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (Integer.bitCount(mask) == sz) {
                int seen = 0;
                int mn = 100, mx = -1;
                boolean ok = true;
                for (int i = 0; i < n; ++i) {
                    if ((mask & (1 << i)) != 0) {
                        int v = nums[i];
                        if ((seen & (1 << v)) != 0) { ok = false; break; }
                        seen |= (1 << v);
                        mn = Math.min(mn, v);
                        mx = Math.max(mx, v);
                    }
                }
                if (ok) valid.add(new int[]{mask, mx - mn});
            }
        }
        int[] dp = new int[1 << n];
        Arrays.fill(dp, (int)1e9);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (dp[mask] == (int)1e9) continue;
            int firstUnset = 0;
            while (firstUnset < n && (mask & (1 << firstUnset)) != 0) firstUnset++;
            if (firstUnset == n) continue;
            for (int[] p : valid) {
                int sub = p[0], cost = p[1];
                if ((sub & (1 << firstUnset)) != 0 && (mask & sub) == 0) {
                    dp[mask | sub] = Math.min(dp[mask | sub], dp[mask] + cost);
                }
            }
        }
        return dp[(1 << n) - 1] >= (int)1e9 ? -1 : dp[(1 << n) - 1];
    }
}

