var minimumIncompatibility = function(nums, k) {
    const n = nums.length;
    const counts = Array(17).fill(0);
    for (const x of nums) {
        if (++counts[x] > k) return -1;
    }
    const sz = Math.floor(n / k);
    if (sz === 1) return 0;
    function popcount(x) {
        let cnt = 0;
        while (x > 0) { cnt += x & 1; x >>= 1; }
        return cnt;
    }
    const valid = [];
    for (let mask = 0; mask < (1 << n); ++mask) {
        if (popcount(mask) === sz) {
            let seen = 0;
            let mn = 100, mx = -1;
            let ok = true;
            for (let i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    const v = nums[i];
                    if (seen & (1 << v)) { ok = false; break; }
                    seen |= (1 << v);
                    mn = Math.min(mn, v);
                    mx = Math.max(mx, v);
                }
            }
            if (ok) valid.push([mask, mx - mn]);
        }
    }
    const dp = Array(1 << n).fill(Infinity);
    dp[0] = 0;
    for (let mask = 0; mask < (1 << n); ++mask) {
        if (dp[mask] === Infinity) continue;
        let firstUnset = 0;
        while (firstUnset < n && (mask & (1 << firstUnset))) firstUnset++;
        if (firstUnset === n) continue;
        for (const [sub, cost] of valid) {
            if ((sub & (1 << firstUnset)) && (mask & sub) === 0) {
                dp[mask | sub] = Math.min(dp[mask | sub], dp[mask] + cost);
            }
        }
    }
    return dp[(1 << n) - 1] === Infinity ? -1 : dp[(1 << n) - 1];
};
